using System.Collections.Generic;

namespace AncientWarfare3.content.figures
{
    internal static class HistoricalFigureCardBiographiesThreeSix
    {
        public static void AddTo(IDictionary<string, string> pEntries)
        {
            pEntries.Add("beiqi_feidi",
                "高殷（545年—561年9月），字正道，北齐第二代皇帝（559年－560年在位），齐文宣帝嫡长子，母亲是昭信皇后李祖娥。天保元年（550年），立为皇太子，时年六岁。性敏慧，但偏于柔懦，高洋对此不满，曾打算立次子太原王高绍德。天保十年（559年），高殷即位，时年十五岁。");
            pEntries.Add("beiqi_houzhudi",
                "齐后主高纬（556年5月29日—577年10月28日至11月25日之间），字仁纲，勃海郡蓨县（今河北省衡水市景县）人，齐武成帝高湛之子，南北朝时期北齐第五位皇帝（565年－577年在位），先后禅位为太上皇与无上皇，史称「后主」。高纬与庶兄高绰同日出生，实为高湛次子，但是因为是嫡出，故被视为长子。高纬即位时，腐朽的北齐政权已经摇摇欲坠，他自己仍然荒淫无道，杀害兄长高绰，导致北齐军队衰弱，政治腐败，尤其最大致命伤是诛杀名将高长恭、斛律光，这使得北齐失去得以抗击北周侵略的有能将领。577年，北周来攻打北齐，占领晋阳，齐军大败，周军不久破北齐京师邺（今河北临漳），高纬慌忙将皇位传于自己8岁的儿子高恒，然后带着幼主高恒等十余人骑马准备投降江南的陈朝。");
            pEntries.Add("beiqi_wenxuan",
                "齐文宣帝高洋（526年—559年11月25日），字子进，鲜卑名侯尼干，勃海郡蓨县（今河北省衡水市景县）人，鲜卑化汉人，因其生于晋阳，又名晋阳乐。为南北朝时期北齐开国与在位最久的皇帝，期间在位10年。他是东魏权臣高欢次子，北齐追尊文襄皇帝高澄的同母弟。");
            pEntries.Add("beiqi_wuchengdi",
                "齐武成帝高湛（537年—569年1月13日），小字步落稽，勃海郡蓨县（今河北省衡水市景县）人，北齐第四位皇帝，561－565年在位，565 - 569年居太上皇，在位四年，实际掌权七年余。东魏权臣高欢第九子，文襄帝高澄、文宣帝高洋、孝昭帝高演之同母弟。高湛少有英姿，幼时极得父亲高欢喜爱。北齐建国后，被齐文宣帝封为长广王。");
            pEntries.Add("beiqi_xiaozhaodi",
                "齐孝昭帝高演（535年—561年11月24日），字延安，勃海郡蓨县（今河北省衡水市景县）人，北齐第三任皇帝（560年－561年在位）。他是东魏权臣高欢第六子，文宣帝同母弟，在位一年。高演长于政术，善于理解事情的细节；天保朝起开始干预朝政，政治经验逐渐成熟丰富，眼见次兄齐文宣帝沉湎酒色，大臣趋炎附势，惟高演满脸忧愁，不时直谏。文宣帝觉察到，对高演说：“有你在处理国事，我为什么不放纵行乐？”高演哭拜在地，沉默不语。");
            pEntries.Add("beiwei_mingyuandi",
                "魏明元帝拓跋嗣（392年—423年12月24日），鲜卑名木末，北魏第二位皇帝，409年—423年在位。北魏道武帝拓跋珪长子，登国七年（392年）生于云中宫，天兴六年（403年），封齐王，拜相国，加车骑大将军。道武帝统治末年，生母刘贵人按子贵母死的制度被道武帝赐死，拓跋嗣知道后悲伤不已，其父北魏道武帝拓跋珪对他的行为感到愤怒。后来道武帝又召见拓跋嗣，但拓跋嗣因为害怕父亲对他不利，因而听从左右的建议出逃在外。");
            pEntries.Add("beiwei_taiwudi",
                "魏太武帝拓跋焘（408年—452年3月11日），鲜卑名佛（bì）狸伐，北魏第三位皇帝（423年12月27日—452年3月11日在位），魏明元帝拓跋嗣的长子，魏道武帝拓跋珪的长孙，在位28年，谥号太武皇帝。拓拔焘即位时，只有十六岁，大臣们都拿他当小孩子看。于是拓拔焘决定先整顿吏治，励精图治，令人刮目相看，北魏国力进入鼎盛。427年，拓跋焘在连续两年突击统万城之后，占领胡夏的北部地区（包含首都统万），并一度攻下关中，胡夏虽迁都至平凉，却于次年（428年）打败魏军并收复关中。");
            pEntries.Add("beiwei_taizu",
                "魏道武帝拓跋珪（371年8月4日—409年11月6日），又名涉珪、什翼圭、翼圭、开，北魏开国皇帝，代王拓跋什翼犍之孙，献明帝拓跋寔和献明皇后之遗腹子。拓跋珪在代王拓跋什翼犍建国三十四年七月七日（东晋太和六年，371年8月4日）在参合陂北出生。建国三十九年（376年），前秦灭代国，拓跋珪将要被强迁至秦都长安，但代王左长史燕凤以拓跋珪年幼，力劝前秦天王苻坚让拓跋珪留在部中，称待拓跋珪长大后为首领，会念及苻坚施恩给代国。苻坚同意，拓跋珪得以留下。");
            pEntries.Add("beiwei_wenchengdi",
                "魏文成帝拓跋濬（440年—465年6月20日），鲜卑名乌雷，拥有「直懃」（直勤）头衔，南北朝时期北魏的第四代皇帝。是魏太武帝的嫡孙，追尊魏景穆帝拓跋晃长子，生母郁久闾氏，452年-465年在位，在位十三年。2001年列为世界文化遗产。");
            pEntries.Add("beiwei_xianwendi",
                "魏献文帝拓跋弘（454年—476年7月20日），字万民，鲜卑名第豆胤，魏文成帝拓跋濬长子，生母李贵人，南北朝时期北魏第六位皇帝。2001年列为世界文化遗产。兴光元年（454年）七月，拓跋弘出生，魏文成帝诏令群臣商议确定皇子的名字，常山王拓跋素、司徒陆丽、尚书左仆射和其奴等人商议说：“古代帝王起名，格式有五种：有信实，有德义，有物象，有假借，有仿照父名。");
            pEntries.Add("beiwei_xiaomingdi",
                "魏孝明帝元诩（510年4月8日—528年3月31日），河南郡洛阳县（今河南省洛阳市东）人，魏宣武帝元恪第二子，生母胡充华，是南北朝时期北魏的皇帝，在位13年。延昌四年（515年），宣武帝病逝，太子元诩继位，由太傅、侍中元怿辅政。胡太后和元怿相爱，常招元怿夜宿宫中。领军元乂和长秋卿刘腾等人密谋，将元怿杀害，又把胡太后幽禁在北宫的宣光殿。");
            pEntries.Add("beiwei_xiaowendi",
                "魏孝文帝元宏（467年10月13日—499年4月26日），本姓拓跋氏，是北魏献文帝拓跋弘的长子，北魏第七位皇帝（471年9月20日—499年4月26日在位），后改姓「元氏」，在位28年，年号太和。其所推行的孝文帝改革，以汉化运动为主体，俗称孝文汉化，其改革措施有利于鲜卑族融入汉族，为社会经济的恢复和发展发挥积极作用。孝文帝去世后，庙号高祖，谥号孝文皇帝。");
            pEntries.Add("beiwei_xiaozhuangdi",
                "魏孝庄帝元子攸（507年—531年1月26日），字彦达，河南郡洛阳县（今河南省洛阳市东）人，魏献文帝拓跋弘之孙，彭城王元勰第三子，母亲为王妃李媛华。孝庄帝是尔朱荣拥立的傀儡皇帝，最终被尔朱兆绞杀。元子攸姿貌很俊美，有勇力。自幼在宫为孝明帝元诩担任伴读，与魏孝明帝颇为友爱，官至中书侍郎，封武城县开国公，527年，被特封长乐王。");
            pEntries.Add("beiwei_xuanwudi",
                "魏宣武帝元恪（483年—515年2月12日），河南郡洛阳县（今河南省洛阳市东）人，魏孝文帝元宏次子，生母贵人高照容，是南北朝时期北魏的第八代皇帝。499年－515年在位，在位十六年，是北魏最后一位拥有实权的皇帝。太和七年（483年），异母兄元恂之生母林氏按北魏子贵母死之惯例而被赐死，元恂由嫡曾祖母冯太后养育。太和十七年（493年）七月，长兄元恂被立为皇太子。");
            pEntries.Add("beizhou_jingdi",
                "宇文阐原名宇文衍，是北周宣帝宇文赟之子，也是北周最后一位皇帝。他年幼即位后由外戚杨坚掌握军政，北周宗室和诸将已无力制衡丞相权力。大定元年宇文阐禅位于杨坚，隋朝由此建立，他随后被封介国公并很快遇害。");
            pEntries.Add("beizhou_mingdi",
                "周明帝宇文毓（534年—560年5月30日），小字统万突，代郡武川镇（今内蒙古自治区呼和浩特市武川县）人，南北朝时代北周的第一代皇帝、第二位天王，557年－560年在位。西魏太师宇文泰庶长子，母亲是夫人姚氏。557年九月因唯一的嫡弟宇文觉被堂兄晋公宇文护所废而即天王位，559年，宇文毓改称皇帝，成为北周开国第一位皇帝。明帝明敏有识量，为宇文护所惮。");
            pEntries.Add("beizhou_wudi",
                "北周武帝宇文邕（543年—578年6月21日），字祢罗突，代郡武川镇人，周文帝宇文泰第四子，北周第二代皇帝。宇文邕17岁即位，因其兄弟先后被宇文护所杀，武帝560年即位后，选择从宇文护不注意的民生入手，修建大荔龙首渠，让民众得以休养生息，韬光养晦。为免自身也遭杀身之祸，对宇文护表示恭敬，让他主理国家大事，以静待时机。十二年后（572年）三月十四以给母亲读《酒诰》之名联合其弟宇文直杀死宇文护，得以亲政。");
            pEntries.Add("beizhou_xiaomindi",
                "周孝闵帝宇文觉（542年—557年），字陀罗尼，代郡武川镇（今内蒙古自治区呼和浩特市武川县）人，北朝西魏权臣宇文泰嫡长子，爵封“周公”，南北朝时代北周的第一位君主，号称天王，但实际上是权臣宇文护的傀儡。557年宇文护拥立宇文觉即位为天王，建立北周。此卡强调北周孝闵帝受宇文护控制、在位不久即被废杀的实际统治经历。");
            pEntries.Add("beizhou_xuandi",
                "周宣帝宇文贇（yūn）（559年—580年6月22日），字乾伯，自称天元皇帝，代郡武川镇（今内蒙古自治区呼和浩特市武川县）人，北周武帝宇文邕长子，北周第四代皇帝（578年－579年），在位只有十个月。北周宣帝武成元年生于同州，是个行事荒唐的皇帝。宇文贇即位前，父亲武帝对他管教极为严格，曾派人监视他的言行举止，甚至只要犯错就会严厉惩罚。建德二年（573年），迎娶隋国公杨坚的长女杨丽华。");
            pEntries.Add("chen_feidi",
                "陈伯宗是南朝陈第三位皇帝，父亲陈文帝陈蒨去世后即位，年号光大。他即位时年幼，朝政主要由叔父陈顼掌握，皇权很快被宗室辅政架空。光大二年陈顼废陈伯宗为临海王并自行称帝，陈伯宗此后在被严密控制的处境中去世。");
            pEntries.Add("chen_wendi",
                "陈文帝陈蒨（522年—566年），一作茜，又名昙蒨，字子华。南北朝时期陈朝第二位皇帝（559年－566年在位），在位7年，年号天嘉。陈蒨是陈朝开国皇帝陈霸先长兄始兴昭烈王陈道谭的儿子，深受陈霸先的赏识与栽培，更令其总理军政。在梁末时期，陈霸先袭杀王僧辩，王僧辩旧部起兵反抗，杜龛派兵五千，攻打陈霸先家乡吴兴的陈氏亲族，陈霸先派遣陈蒨提早返回吴兴长城县，组织亲族建好防御工事，面对五千敌军，麾下只有数百人的陈蒨却神情自若、处之泰然，工事内的人心得以稳定，杜龛的军队围攻数百日，无法攻克。");
            pEntries.Add("chen_wudi",
                "陈武帝陈霸先（503年—559年），字兴国，小字法生，吴兴郡长城县（今浙江长兴）人，南北朝时代陈朝开国皇帝。557年接受梁敬帝萧方智的禅位建立陈朝，557年－559年在位。死后庙号高祖，谥号武皇帝。");
            pEntries.Add("chen_xuandi",
                "陈宣帝陈顼（530年8月14日—582年2月17日），又名陈昙顼，字绍世，小字师利，南北朝时期陈朝第四位皇帝（569年－582年在位），正式谥号为「孝宣皇帝」，后世比照汉朝和西晋皇帝省略「孝」字，称「陈宣帝」，在位14年，年号太建。陈顼出生于南朝梁中大通二年（530年）七月初六日（8月14日）。陈顼是高祖武皇帝陈霸先的侄子，始兴昭烈王陈道谭第二子，世祖文皇帝陈蒨的弟弟，封安成王。他本来是皇帝陈伯宗的辅佐大臣，后来在光大二年（568年）11月，陈顼叛逆废陈伯宗为临海王，自立为帝，是为陈宣帝。");
            pEntries.Add("dongwei_xiaojingdi",
                "魏孝静帝元善见（524年—552年1月21日），河南郡洛阳县（今河南省洛阳市东）人，魏孝文帝元宏曾孙，清河文宣王元亶嫡子，母清河王妃胡智，南北朝时期东魏唯一一代皇帝。魏孝静帝出生于公元524年。永熙三年（西元534年）七月，魏孝武帝从洛阳出逃，投靠在长安的宇文泰。元善见父元亶原本自以为可以被权臣高欢拥立为帝，但十月，高欢和百僚详细商议后，决定立元善见为皇帝，承嗣魏孝明帝元诩。");
            pEntries.Add("feng_ba",
                "北燕文成帝冯跋（？—430年），字文起，小名乞直伐，十六国时期北燕君主，为胡化的汉人，长乐郡信都县（今河北省衡水市冀州区）人。冯跋是冯和之孙，其父冯安曾任西燕将军。西燕亡，冯跋东迁后燕，于后燕惠愍帝慕容宝在位时被任命为中卫将军。");
            pEntries.Add("fu_jian_351",
                "秦景明帝苻健（317年—355年7月10日），字建业，略阳临渭（今甘肃秦安）人，氐族，苻洪第三子，十六国前秦开国皇帝。苻健继父亲苻洪统领部众并成功入关，定都长安（今陕西西安），建立前秦。后屡次作战征服其他反抗前秦的关内势力，更击败北伐的晋军。");
            pEntries.Add("gao_huan",
                "高欢（496年—547年2月13日），鲜卑名贺六浑，勃海郡蓨县（今河北省衡水市景县）人，鲜卑化汉人，北魏、东魏权臣，任职相国，爵封「渤海王」，谥「献武」，也是北齐政权的奠基者。追尊为「神武帝」，也常被称作「高王」。此卡以高欢作为东魏实际统治者和北齐政权奠基人的君主身份收录。");
            pEntries.Add("helian_bobo",
                "夏武烈帝赫连勃勃（381—425），原名刘勃勃，匈奴铁弗部人，东晋十六国时期胡夏建立者。他是南匈奴单于刘去卑的后裔，铁弗部酋长刘卫辰之子。其父刘卫辰因被北魏击败身死，部族亦溃散，幸免下的刘勃勃遂投奔后秦高平公、鲜卑酋长没弈干，并娶其女。随着年龄渐长，刘勃勃“身长八尺五寸，腰带十围，性辩慧，美风仪”，获后秦皇帝姚兴器重，任命为将军，统率后秦收拢的铁弗余部及朔方杂胡三万人，负责抵御北魏。");
            pEntries.Add("hou_jing",
                "侯景（503年—552年5月26日），字万景，朔方人（或说是雁门人），父亲侯标，祖父乙羽周，南北朝侯景之乱的主谋。北魏后期叛乱多发，此起彼伏。经过河阴之变，尔朱荣掌握了政权，他开始对各地的反抗力量进行征剿。此时侯景率领自己的部队投靠了尔朱荣，并获尔朱荣任命为先锋。此卡以侯景攻陷建康后建立汉政权、自称皇帝的叛乱君主身份收录。");
            pEntries.Add("huan_xuan",
                "桓玄（369年—404年6月19日），字敬道，一名灵宝，谯国龙亢县（今安徽省蚌埠市怀远县）人，谯国桓氏代表人物，东晋名将桓温之子，东晋末期桓楚政权建立者。曾消灭殷仲堪和杨佺期占据荆江广大土地，后更消灭了掌握朝政的司马道子父子，掌握朝权。次年桓玄就篡位建立桓楚，但三个月后刘裕就举义兵反抗桓玄，桓玄不敌而逃奔江陵重整军力，但后再遭西讨的义军击败。试图入蜀途中遇上护送毛璠灵柩的费恬等人，遭益州督护冯迁杀害。");
            pEntries.Add("jin_aidi",
                "晋哀帝司马丕（341年—365年3月30日），字千龄，河内郡温县（今河南省焦作市温县）人，东晋皇帝，晋成帝之子，晋穆帝之堂兄。342年封为琅琊王，345年拜散骑常侍。356年加中军将军，359年十二月除骠骑将军。晋哀帝本应继晋成帝之位即位，但是由于权臣庾冰的意见而无法即位；司马丕于361年在晋穆帝死后即位，改元隆和，但是大将桓温当国，晋哀帝形同傀儡。");
            pEntries.Add("jin_andi",
                "晋安帝司马德宗（382年—419年1月28日），字德宗，河内郡温县（今河南省焦作市温县）人，东晋皇帝。晋孝武帝司马曜的长子，母亲是陈归女。晋安帝由于痴愚而无能力掌握国政，在位廿二年间朝权都旁落在臣下之中，国内内乱频仍，期间甚至发生了桓玄代晋的事件。东晋国祚在北府将领刘裕主持下获得恢复，但亦为刘裕奠下建立刘宋的基础，安帝自己因刘裕欲代晋而遇害。");
            pEntries.Add("jin_chengdi",
                "晋成帝司马衍，字世根，东晋皇帝，晋明帝之长子。晋成帝年幼即位，即位不久即遇上苏峻之乱，成帝亦一度遭苏峻叛军劫持。成帝一朝军政主要由外戚颖川庾氏把持，在庾亮的主导下还曾谋北伐，但因后赵强盛而遭到失败。");
            pEntries.Add("jin_feidi",
                "司马奕（342年—386年11月23日），字延龄，河内郡温县（今河南省焦作市温县）人，东晋皇帝，晋成帝之子、晋哀帝之弟。晋哀帝死后于365年即帝位，后世称「废帝」。342年六月封为东海王，352年拜散骑常侍、镇军将军。360年升车骑将军，361年改封琅琊王。");
            pEntries.Add("jin_gongdi",
                "晋恭帝司马德文（386年—421年11月2日），字德文，河内郡温县（今河南省焦作市温县）人，东晋的末代皇帝。为晋孝武帝之子，晋安帝之胞弟，母亲是淑媛陈归女。初封琅邪王，后在桓玄篡位后长期侍奉晋安帝左右。晋安帝死后被刘裕矫以遗诏立为皇帝，但其时刘裕已经完全掌握东晋朝政，司马德文仅为傀儡而已。");
            pEntries.Add("jin_huaidi",
                "晋怀帝司马炽（284年—313年3月14日），字丰度，西晋皇帝，司马炎的第二十五子，其正式谥号为「孝怀皇帝」，后世省略「孝」字称「晋怀帝」。司马炽生于太康五年（284年），生母为晋武帝中才人王媛姬，王媛姬早逝后由武帝继后武元皇后杨芷抚养。武帝太熙元年（290年）司马炽被封为豫章王，四月，司马炎病死。太子司马衷即位，是为晋惠帝，在晋惠帝在位期间爆发的八王之乱中，司马炽并未加入乱事，并且行事低调，不太热衷于交结宾客，爱好钻研史籍。");
            pEntries.Add("jin_huidi",
                "司马衷即晋惠帝，继承晋武帝后因缺乏处理政务的能力，朝权先后落入杨骏、贾南风和宗室诸王之手。皇后贾南风废杀太子司马遹，引发赵王伦夺权和持续多年的八王之乱。惠帝在洛阳、长安之间多次被军队挟持，西晋中枢由此崩溃并为永嘉之乱埋下直接祸根。");
            pEntries.Add("jin_kangdi",
                "晋康帝司马岳（322年—344年11月17日），字世同，东晋皇帝。晋康帝是晋明帝之子，母庾文君，是晋成帝的同母弟。晋康帝于326年被封为吴王，后封琅琊王，342年晋成帝死后，由于权臣庾冰与庾翼力主之故，晋康帝才得以用兄终弟及的方式继承帝位，但不久便于建元二年344年患病驾崩，时年二十三岁，葬于崇平陵，其子司马聃继位。《晋书·卷七·帝纪第七·成帝 康帝》。");
            pEntries.Add("jin_mindi",
                "晋愍帝司马邺（300年—318年2月7日），字彦旗，西晋第四任也是最后一任皇帝。司马邺为吴王司马晏之子，晋武帝司马炎之孙，外祖父是济北成侯中书监荀勖。316年刘曜陷长安，西晋灭亡，汉赵昭武帝刘聪降封怀安侯，后被杀。其正式谥号为「孝愍皇帝」，后世省略「孝」字称「晋愍帝」。");
            pEntries.Add("jin_mingdi",
                "司马绍即晋明帝，是东晋元帝之子，以敏锐果断著称。他即位后面对王敦再次举兵，亲自部署建康防务，并在王敦病死后迅速平定其党羽，暂时恢复皇权。明帝在位不足三年便病逝，幼子继位后东晋政治重新转入外戚与士族辅政。");
            pEntries.Add("jin_mudi",
                "晋穆帝司马聃（343年—361年7月10日），字彭子，东晋皇帝，庙号孝宗。晋穆帝是晋康帝之子，母褚蒜子。建元二年（344年），由于晋康帝仅22岁便驾崩，晋穆帝即位，时年两岁；由于年幼而由褚太后掌政，并由何充辅政。何充过世后改由蔡谟与司马昱辅政。");
            pEntries.Add("jin_wudi",
                "晋武帝司马炎（236年—290年5月16日）， 字安世，河内郡温县（今河南焦作温县）人。三国魏国权臣司马懿之孙，晋王司马昭长子，晋朝（西晋）开国皇帝，在位二十五年。在位期间采取一系列经济措施以发展生产，屡次责令郡县官劝课农桑，并严禁私募佃客。又招募原吴、蜀地区人民北来，充实北方，并废屯田制，使屯田民成为州郡编户。");
            pEntries.Add("jin_xiaowudi",
                "晋孝武帝司马曜（362年—396年11月6日），字昌明，河内郡温县（今河南省温县）人，东晋皇帝，在位时间是372年至396年。他是晋简文帝的第六个儿子，晋安帝和晋恭帝的父亲，母李陵容。晋孝武帝四岁时被封为会稽王，372年9月12日被立为太子，同日晋简文帝逝，继位时年仅十一岁。次年年号为宁康，由褚太后（堂兄晋康帝遗孀）摄政。");
            pEntries.Add("jin_yuandi",
                "晋元帝司马睿（276年5月27日—323年1月3日），字景文，东晋皇帝。司马懿的曾孙，琅邪武王司马伷之孙，琅邪恭王司马觐之子，母为琅邪王妃夏侯光姬。司马睿在八王之乱期间政治上从属于东海王司马越集团，并在其西征河间王司马顒时受指命镇守下邳后方。后司马睿南镇建业，在琅邪王氏为首的士族协助下建立起江南政权，并在西晋灭亡后延晋祚，建立东晋。");
            pEntries.Add("juqu_mengxun",
                "凉武宣王沮渠蒙逊（368年—433年），临松匈奴人，十六国时期北凉第二任君主，亦是北凉的实际缔造者。原系匈奴支系卢水胡族首领，曾反叛后凉并推段业建北凉，后攻杀段业自己登位。沮渠蒙逊有勇略，在位期间，北凉于强敌环伺之际扩张成为河西一带最强大的势力。");
            pEntries.Add("li_gao",
                "凉武昭王李暠（hào）（351年—417年），字玄盛，小字长生，陇西郡狄道县（今甘肃省定西市临洮县）人，十六国时期西凉的建立者，唐朝皇室和诗人李白皆称李暠为其先祖。天宝二年（743），唐玄宗追尊李暠为兴圣皇帝。自称是前凉武卫将军李昶的遗腹子，李暠年少好学，性格宽和，读遍经史，尤能理解文章的义理。李暠长大后也学习武艺，读孙吴兵法。");
            pEntries.Add("li_xiong",
                "成武帝李雄（274年—334年），字仲儁，氐人，十六国时期成汉开国皇帝（304年至334年在位）。304年李雄自称成都王，建年号建兴。306年正式称帝，国号大成，史称成汉。");
            pEntries.Add("liang_jianwendi",
                "梁简文帝萧纲（503年12月2日—551年11月15日），字世赞，一作世缵，小字六通，梁武帝萧衍第三子，昭明太子萧统的胞弟，母丁令光。梁武帝死后，被作乱的权臣侯景拥立为帝，后又为侯景所废并杀害。梁简文帝萧纲生于天监二年十月丁未（503年12月2日），最早封为晋安王，食邑八千户。天监八年（509年），任云麾将军，领石头戍军事。");
            pEntries.Add("liang_jingdi",
                "梁敬帝萧方智（543年—558年5月5日），字慧相，南梁的末代皇帝，梁元帝萧绎的第九子，母夏贵妃。549年，萧方智被封兴梁侯；552年加封晋安王，553年出任平南将军、江州刺史。554年，梁元帝在江陵被杀，在陈霸先、王僧辩支持下，萧方智称梁王、入建康，以太宰承制。555年，北齐将元帝堂兄贞阳侯萧渊明送回之后，王僧辩因无力抵抗，转为拥立萧渊明为皇帝，将萧方智立为皇太子。");
            pEntries.Add("liang_wudi",
                "梁武帝萧衍（464年—549年），字叔达，小字练儿。南兰陵中都里人（今江苏常州市武进区西北）。南北朝时代南梁开国皇帝，庙号高祖。萧衍是南齐宗室，亦是兰陵萧氏的世家子弟，出生在秣陵（今南京），父亲萧顺之是齐高帝的族弟，封临湘县侯，官至丹阳尹。");
            pEntries.Add("liang_yuandi",
                "梁元帝萧绎（508年9月16日—555年1月27日），字世诚，梁武帝萧衍的第七子，正式谥号为「孝元皇帝」，后世比照西汉的汉元帝，省「孝」字称「梁元帝」。萧绎于514年封湘东王，早年因病而一眼失明。547年出荆州，任荆州刺史、使持节、都督荆雍湘司郢宁梁南北秦九州诸军事、镇西将军。侯景之乱时，梁武帝遣人至荆州宣读密诏，授萧绎为侍中、假黄钺、大都督中外诸军事、司徒承制，其余职务如故。");
            pEntries.Add("liu_yuan",
                "汉光文帝刘渊（约250年—310年8月19日），字元海，新兴匈奴人（今山西忻州市北），出身南匈奴的屠各部。为五胡十六国时代中，汉赵的开国君王。西晋末年八王之乱时诸王互相攻伐，南匈奴人拥立其为大单于。304年，刘渊乘朝廷内乱而在并州自立，称汉王，国号为汉（后改为赵，史称前汉、前赵或汉赵），5年后称帝，改元永凤。");
            pEntries.Add("lu_guang",
                "凉懿武帝吕光（338年—399年），字世明，天水郡古县（今甘肃省天水市）人，氐族，前秦太尉吕婆楼之子。吕光初为前秦将领，屡立战功，前秦天王苻坚就派他使持节、都督西出兵西域。吕光降服西域，但当时前秦因淝水之战战败而发生内乱，前后分别有后燕、西燕、西秦、后秦纷纷建国。前秦太安元年（公元385年）吕光从西域率军回军时击溃凉州刺史梁熙进入姑臧，自封为凉州刺史及护羌校尉。");
            pEntries.Add("murong_chui",
                "燕成武帝慕容垂（326年—396年6月2日），字道明，原名霸，字道业，一说字叔仁，鲜卑名阿六敦，昌黎棘城（今辽宁义县）鲜卑族人。前燕文明帝慕容皝的第五子。在前燕时屡有战功，更曾击退东晋桓温的北伐军。受到当政的慕容评排挤，被逼出走前秦，受到前秦君主苻坚的宠信，与王猛一同灭亡前燕。");
            pEntries.Add("murong_de",
                "燕献武帝慕容德（336年—405年11月17日），后改名慕容备德，字玄明，十六国时期南燕皇帝，鲜卑人，是前燕文明帝慕容皝之幼子，前燕景昭帝慕容儁、后燕成武帝慕容垂皆为其兄。《晋书》载其「年未弱冠，身长八尺二寸，姿貌雄伟」。又「博观群书，性清慎，多才艺」。");
            pEntries.Add("murong_hong",
                "慕容泓（350年代—384年），十六国时期西燕国建立者，鲜卑人。前燕帝慕容儁之子，慕容暐之弟。前燕时期慕容儁在位时被封为济北王。370年，前燕为前秦所灭后，包括慕容泓在内的众多鲜卑慕容部人被迁往关中。");
            pEntries.Add("murong_huang",
                "燕文明帝慕容皝（huàng）（297年—348年10月25日），字元真，小字万年，昌黎棘城（今辽宁义县）鲜卑族人。中国五胡十六国时代前燕政权奠基人，不过当时仍名义上臣属于东晋，直至其子慕容儁正式称帝后，才追尊庙号太祖，谥号为文明皇帝。慕容皝勇武刚毅且多有谋略，崇尚经学，熟悉天文。建武初年拜冠军将军、左贤王、封望平侯。");
            pEntries.Add("qi_donghunhou",
                "萧宝卷（483年—501年12月31日），字智藏，原名萧明贤，南齐的第六代皇帝，为齐明帝萧鸾第二子。萧宝卷年少时不喜读书，以捕老鼠为乐。498年，萧宝卷在萧鸾死后即位，这时萧宝卷才十六岁。他封潘玉儿为贵妃，潘贵妃生下一个女儿，封为公主，但公主却百日而殇，萧宝卷制斩衰絰杖，积旬不听音乐，衣悉粗布。");
            pEntries.Add("qi_gaodi",
                "齐高帝萧道成（427年—482年4月11日），字绍伯，小字鬬将，南兰陵兰陵（今江苏武进）人。南北朝时代军事家、政治家，南朝第二个皇朝南齐开国皇帝。萧道成出身将门，以戎旅起家，屡次征伐外敌、平定内乱有功。刘宋末年政治混乱，道成入朝累官为「四贵」权臣，后来更参预废立，终于篡宋建齐。此卡以萧道成代宋建齐、即位为南齐高帝后的开国皇帝身份收录。");
            pEntries.Add("qi_heshandi",
                "齐和帝萧宝融（488年—502年），字智昭，南齐的末代皇帝，齐明帝萧鸾第八子，母萧鸾原配追赠皇后刘惠端。494年十一月被封为随郡王，499年正月改封为南康王，持节，都督荆、雍、益、宁、梁、南秦、北秦七州军事，任为西中郎将、荆州刺史，驻守江陵。501年三月，萧衍发兵攻打萧宝卷，并且与行荆州府事萧颖胄合谋，让萧宝融自称相国，后又立萧宝融为皇帝，以萧宝融名义废萧宝卷为庶人，萧颖胄辅佐萧宝融守江陵，萧衍东征。萧衍手下劝他把萧宝融带到襄阳以免便宜了挟天子以令诸侯的萧颖胄，萧衍拒绝，认为此次起兵如果失败了此举就没有意义，如果成功了再寻找夺权的机会也不迟。");
            pEntries.Add("qi_mingdi",
                "齐明帝萧鸾（452年—498年9月1日），字景栖，小名玄度，庙号高宗，谥明皇帝，南齐第五任皇帝。为始安贞王萧道生之子、齐高帝萧道成之侄。他在494年至498年期间在位，共5年。");
            pEntries.Add("qi_wudi",
                "萧赜继承父亲萧道成，是南齐第二位皇帝，年号永明。他在位时提倡节俭、减省徭役并整顿地方行政，任用王俭等文臣维持较稳定的朝局，史称永明之治。晚年太子萧长懋早逝使继承秩序动摇，后来宗室内斗逐渐破坏了这一时期的成果。");
            pEntries.Add("qifu_guoren",
                "乞伏国仁（？—388年），陇西鲜卑人。十六国时期西秦政权奠定者。在前秦官至前将军，淝水之战后乘机自立，但仍与前秦保持一定关系。虽然一般认为乞伏国仁是西秦建立者，惟其在位期间，只受前秦封为苑川王，尚未正式称秦王。");
            pEntries.Add("ran_min",
                "冉闵（320年代—352年6月1日），有文献记为“染闵”，字永曾，小字棘奴，魏郡内黄人（今河南安阳市内黄县西北），出生于兰陵郡（今山东枣庄和山东临沂交界的地方），中国五胡十六国时期后赵君主石虎的养孙，冉魏君主。冉闵的父亲冉瞻（后改名石瞻）是汉人，原乞活军陈午部下，随陈午投降石勒。在十六国中后赵的国君羯人石虎的部下担任将领，并成爲石虎养子，于是改姓石。史书记载，石瞻“骁猛多力，攻战无前。");
            pEntries.Add("shi_le",
                "赵明帝石勒（274年—333年8月17日），字世龙，小字匐勒，上党武乡（今山西榆社）羯人，是五胡十六国时代后赵的开国君主。石勒早年为奴隶，初期因公师藩而起兵，后投靠汉赵君主刘渊，之后却与汉国决裂，由汉国分裂出去。石勒在他的谋臣，汉人张宾辅助之下以襄国（今河北邢台）为根据地，并陆续消灭了王浚、邵续、段匹磾等西晋于北方的势力，继而又消灭曹嶷，进侵东晋以及消灭刘曜领导的前赵，又北征代国，率领后赵成为当时北方最强盛的国家。石勒又实行多项措施，推动文教和经济发展。");
            pEntries.Add("shu_han_zhaolie",
                "汉昭烈帝刘备（161年—223年6月10日），字玄德，涿郡涿县（今河北省涿州市）人，三国时代蜀汉的开国皇帝，在位三年。《三国志》、《华阳国志》等书均称其为先主，继位的刘禅则被称为「后主」，《资治通监》称刘备父子为汉主。后世也用谥号“昭烈”代指刘备。刘备原与同宗刘德然、辽西人公孙瓒一起拜卢植为师学习。");
            pEntries.Add("shu_hou_zhu",
                "刘禅（shàn）（禅又音禅（chán），207年—271年），字公嗣，又字升之，幼名阿斗。汉昭烈帝刘备之子，蜀汉最后一位皇帝。陈寿着《三国志》称其为后主，十六国时期的汉赵政权谥其为孝怀皇帝，史称汉怀帝或蜀汉后主。刘禅在位达41年（223年－263年），是整个三国时期在位时间最长的君主。");
            pEntries.Add("song_houfeidi",
                "刘昱（yù）（463年3月1日—477年8月1日），字德融，小字慧震，史称“后废帝”，是刘宋第八任皇帝，宋文帝孙，宋明帝长子，母是贵妃陈妙登。在位五年，终为臣下萧道成所弑，不久篡宋自立，国号齐，登基后杀死包括顺帝在内的明帝诸子及刘宋宗室。刘昱在大明七年正月辛丑日（463年3月1日）出生于衞尉府。宋明帝即位后，在消灭反对自己的晋安王刘子勋政权后，于十月戊寅日（466年11月17日）册立刘昱为皇太子。");
            pEntries.Add("song_mingdi",
                "宋明帝刘彧（439年12月9日—472年5月10日），字休炳，小字荣期，南朝宋第七任皇帝。刘彧生于元嘉年间，为宋文帝刘义隆第十一子，先后受封淮阳王、湘东王。宋前废帝刘子业即位，顾虑诸叔威胁皇位，趁刘彧入朝时将其拘留殿中，并因刘彧体胖而封其为「猪王」，大肆羞辱，且屡次欲加杀害，都因始安王刘休仁谄媚化解，才保全性命。刘子业遭寿寂之杀害后，刘休仁便奉迎刘彧即皇帝位，改元泰始，大赦天下。");
            pEntries.Add("song_qianfeidi",
                "刘子业（449年2月25日—466年1月1日），小字法师，南北朝时期南朝宋皇帝，史称「前废帝」。为宋武帝曾孙，宋文帝孙，宋孝武帝刘骏长子，生母为文穆皇后王宪嫄。宋前废帝以皇太子身份即位，但即位之初受制于掌权大臣而难以专政，遂于即位一年后将主政大臣戴法兴诛杀，接着又将图谋废立的三名顾命大臣杀害，其中更残忍肢解叔祖父江夏王刘义恭。此后前废帝肆意行事，荒淫无道，做出很多残暴甚至乱伦的行为，约半年后就在阮佃夫等人策划下，被主衣寿寂之刺杀。");
            pEntries.Add("song_shaodi",
                "刘义符（406年—424年8月4日），小字车兵，彭城绥舆里（今安徽省萧县）人。中国南北朝时期宋朝的第二位皇帝，宋武帝刘裕长子，母亲是夫人张氏。永初三年（422年）即位为帝，但两年后就因居丧行为不当而遭顾命大臣徐羡之、傅亮等废黜，不久被杀。");
            pEntries.Add("song_shundi",
                "宋顺帝刘准（467年8月8日—479年6月23日），字仲谋，小字智观，为刘宋的末代皇帝，宋文帝孙，宋明帝刘彧的第三子。但《宋书》却说宋明帝晚年阳痿，无法生育，所以刘准其实是刘彧之弟桂阳王刘休范与姬妾的儿子，由陈法容所抚养。不过这项记载被史家吕思勉驳斥，认为是《宋书》的作者沈约（南齐的史官）为了讨好南齐皇帝，故意编造这样的史料，好掩饰萧道成篡位、弑君的罪恶。");
            pEntries.Add("song_wendi",
                "宋文帝刘义隆（407年—453年3月16日），小字车儿，宋武帝刘裕的第三子，刘宋第三任皇帝。刘义隆生于东晋末年，南朝宋立国后，受封宜都王。宋少帝被废后获拥立为帝，即位后改元元嘉。刘义隆在位近三十年，在位期间，建立制度、赏罚分明、鼓励农桑，减免赋税力役，使得国家大治，「内清外晏，四海谧如」，此治世因其年号元嘉而称为「元嘉之治」。");
            pEntries.Add("song_wudi",
                "宋武帝刘裕（363年4月16日—422年6月26日），字德舆，小字寄奴，彭城郡彭城县绥舆里（今安徽省萧县）人，汉族人，东晋末年至南北朝初期的军事家、政治家，南北朝时期刘宋的开国皇帝。刘裕出身贫寒，最初为北府将领孙无终的司马，在孙恩之乱中初露军事才能，及后更发起义军击败篡位的桓玄，恢复东晋政权，再次扶持晋安帝上位，获得极高名望，不久之后掌握朝政大权。刘裕趁南燕内讧之际而出兵灭燕，随后又平定了卢循之乱，并消灭了刘毅、诸葛长民及司马休之等异己，巩固了自己在东晋国内的地位。此卡以刘裕受禅建宋、成为刘宋开国皇帝后的君主身份收录。");
            pEntries.Add("song_xiaowu",
                "宋孝武帝刘骏（430年9月19日—464年7月12日），字休龙，小字道民，宋文帝刘义隆的第三子，南朝宋第四任皇帝。453年3月16日深夜，皇太子刘劭于京城建康（今南京市）行凶，杀害父皇宋文帝刘义隆，自称皇帝；时为武陵王的刘骏在沈庆之的辅佐下，于江州（今九江市）起兵宣讨。同年5月20日，于新亭（今南京市西南）即皇帝位。5月27日攻下京城，擒斩长兄刘劭、二兄刘濬。");
            pEntries.Add("three_cao_cao",
                "曹操（155年—220年3月15日），字孟德，小字阿瞒，沛国谯县（今安徽亳州）人。东汉末年丞相、军事家、政治家、文学家和诗人，东汉末年主要群雄之一，职位为丞相，为汉末实际上的最高掌权者，亦是三国时代曹魏奠基者。其子曹丕建立曹魏，追尊其庙号为太祖，追谥武皇帝。早年与袁绍相处甚厚，袁绍与何进欲尽诛阉宦，引董卓入京。");
            pEntries.Add("three_chen_lin",
                "陈琳（？—217年），字孔璋，广陵射阳（今江苏扬州宝应东北）人。汉灵帝末年，陈琳任大将军何进主簿，中平六年（189年）何进因何太后拒绝交出宦官，而欲招引诸侯入宫作兵谏。陈琳以「掩目捕雀」讽刺何进自己骗自己，认为应闪电杀进宫中，引外兵入宫只会招来大乱。");
            pEntries.Add("three_chen_qingzhi",
                "陈庆之（484年—539年），字子云，义兴郡国山县（今江苏省宜兴市）人，中国南北朝南朝梁武将。从梁武帝东下平建邺，稍为主书。期间散尽钱财，招集将士，常想有一天能为朝廷效力。普通中，北魏徐州刺史元法僧于彭城求入内附，以陈庆之为武威将军，与胡龙牙、成景儁率诸军应接。");
            pEntries.Add("three_chen_qun",
                "陈群出身颍川士族，先后服务刘备、曹操和曹丕，是曹魏中枢的重要文臣。他主持创立九品中正制，以地方中正品评人物并作为选官依据，帮助新政权整合士族人才。这一制度后来逐渐强化门第优势，深刻影响魏晋南北朝的官僚结构与社会阶层。");
            pEntries.Add("three_chen_shou",
                "陈寿（233年－297年），字承祚，巴西郡安汉县（今四川省南充市）人，蜀汉至西晋时期的历史学家。陈寿早年师从同郡学者谯周，在蜀汉任观阁令史等职；蜀汉亡后入仕西晋，历任佐着作郎、阳平令、着作郎等职。西晋统一后，陈寿在魏、吴既有官修史书及蜀汉史料的基础上编纂《三国志》六十五卷，分别记述魏、蜀、吴三国历史，后列入二十四史。其着作另有《蜀相诸葛亮集》《古国志》《益部耆旧传》等，多已亡佚。");
            pEntries.Add("three_cheng_yu",
                "程昱（141年—220年），字仲德，兖州东郡东阿（今山东省聊城市东阿县）人，三国时代曹魏将领和政治家。原名程立，因梦中于泰山捧日，被曹操更名程昱，谥肃侯。黄巾之乱时，东阿县县丞王度呼应乱军，在地方造反，烧掉县中的仓库。东阿县令弃城逃走，城中吏民负老携幼向东逃到渠丘山。");
            pEntries.Add("three_cui_hao",
                "崔浩（381年—450年7月5日），字伯渊，清河郡东武城县（今河北省衡水市故城县）人。中国南北朝时期的北魏政治家。崔浩出身于清河崔氏，是崔玄伯的长子，母亲卢氏是卢谌的孙女。《魏书·崔浩列传》说他：“少好文学，博览经史。");
            pEntries.Add("three_deng_ai",
                "邓艾（197年—264年），字士载，本名邓范，字士则，后因与同乡人同名而改名，义阳棘阳（今河南新野）人，三国时曹魏后期名将。邓艾多年在曹魏西边战线防备蜀汉姜维，后来偷渡阴平，逼使蜀帝刘禅投降，建立灭蜀奇功，获封太尉。但战后被锺会构陷谋反而被押解，不久后锺会叛乱失利，邓艾帐下军官打算营救邓艾，然而卫瓘等锺会旧部怕受邓艾报复，便遣田续先行杀死邓艾，其子邓忠亦同殉此难。");
            pEntries.Add("three_ding_yi",
                "丁仪是东汉末年文士，因才名受到曹操注意，并进入曹氏幕府参与文书与议论。他在曹丕、曹植的继承竞争中坚定支持曹植，与杨修等人同属曹植集团。曹丕即魏王位后清算政敌，丁仪及其弟丁廙被诛，其结局反映建安文士卷入储位斗争的风险。");
            pEntries.Add("three_du_yu",
                "杜预（222年—285年），字元凯，京兆郡杜陵县（今陕西省西安市）人，曹魏末与西晋前期高级官员、军事家、经学家。出于京兆杜氏，西汉御史大夫杜延年十一世孙，亦是襄阳杜氏先祖。司马昭当政时，杜预娶了司马昭妹妹高陆公主，官拜尚书郎，承袭其父杜恕原爵丰乐亭侯。景元四年（263年），镇西将军锺会领兵讨伐蜀汉，杜预当时以镇西长史随军。");
            pEntries.Add("three_fa_zheng",
                "法正（176年—220年），字孝直。东汉司隶右扶风郿（今陕西眉县）人，三国时蜀汉重臣；深有谋略，定军山之战策划袭杀夏侯渊。刘备在世时，惟独法正有谥号，死后追谥为翼侯。与曹魏谋士程昱和郭嘉一样有性格缺陷（程昱太刚直易得罪人、郭嘉行为不检、法正则是睚眦必报），但同样善策奇谋，故陈寿誉其可比二人。");
            pEntries.Add("three_gao_huan",
                "高欢（496年—547年2月13日），鲜卑名贺六浑，勃海郡蓨县（今河北省衡水市景县）人，鲜卑化汉人，北魏、东魏权臣，任职相国，爵封「渤海王」，谥「献武」，也是北齐政权的奠基者。追尊为「神武帝」，也常被称作「高王」。此卡以高欢从六镇军人崛起、控制北魏朝廷并拥立孝静帝的权臣身份收录。");
            pEntries.Add("three_guo_jia",
                "郭嘉早年离开袁绍阵营，经荀彧推荐进入曹操幕府，担任司空军祭酒并参与核心军事谋划。他支持曹操先击吕布、判断孙策将死于轻率行事，又在官渡前分析曹操“十胜”、袁绍“十败”，帮助稳定决策信心。北征乌桓时郭嘉主张轻装疾进，曹军在白狼山取胜，但他在归途中病逝，曹操后来常以其早亡为憾。");
            pEntries.Add("three_guan_yu",
                "关羽字云长，河东解县人，东汉末年追随刘备起兵，与张飞长期担任其核心将领。官渡之战前后他曾暂归曹操，在白马阵斩杀颜良后离开，后来镇守荆州并发动襄樊战役，一度擒于禁、斩庞德而威震华夏。孙权派吕蒙袭取荆州后，关羽败走麦城并被杀；其忠勇形象此后不断受到朝廷敕封和民间崇祀，最终成为影响广泛的关帝信仰。");
            pEntries.Add("three_hou_jing",
                "侯景（503年—552年5月26日），字万景，朔方人（或说是雁门人），父亲侯标，祖父乙羽周，南北朝侯景之乱的主谋。北魏后期叛乱多发，此起彼伏。经过河阴之变，尔朱荣掌握了政权，他开始对各地的反抗力量进行征剿。此时侯景率领自己的部队投靠了尔朱荣，并获尔朱荣任命为先锋。此卡以侯景先后服务北魏、东魏与梁朝的将领身份收录，侧重其叛梁前的军政经历。");
            pEntries.Add("three_huan_wen",
                "桓温（312年—373年8月18日），字元子，谯国龙亢县（今安徽省怀远县）人。东晋重要将领及权臣、军事家，谯国桓氏代表人物。宣城内史桓彝长子，因领兵消灭成汉而声名大盛，又曾三次领导北伐，掌握朝政并曾操纵废立，更有意夺取帝位，但终因最后一次北伐大败而令声望受损，受制于朝中王氏和谢氏势力而未能如愿。死前欲得九锡亦因谢安等人借故拖延，直至去世时也未能实现。");
            pEntries.Add("three_jia_xu",
                "贾诩早年在董卓旧部中任职，董卓死后建议李傕、郭汜反攻长安，使汉末政局再次陷入军阀控制。他后来辅佐张绣，两次使曹操受挫，又判断形势劝张绣归降曹操。官渡、潼关及曹氏继承问题中贾诩多次提出审慎策略，最终支持曹丕并在魏国官至太尉。");
            pEntries.Add("three_jiang_wei",
                "姜维（202年—264年3月3日），字伯约，凉州天水郡冀县（今甘肃省天水市甘谷县）人，三国时期蜀汉着名军事家。姜维早年仕于曹魏，任天水郡中郎、参郡军事。建兴六年（228年），诸葛亮第一次北伐时，天水太守马遵怀疑姜维等人有异心，拒绝其入城，姜维遂投奔蜀汉。诸葛亮器重其才，任命他为仓曹掾、奉义将军，并封当阳亭侯。");
            pEntries.Add("three_liu_fang",
                "刘放（2世纪—250年），字子弃，涿郡方城县（今河北省廊坊市固安县）人，是西汉广阳顷王刘建之子西乡顷侯刘容的后代，三国时代魏国大臣。刘放早年担任过郡纲纪，被荐举为孝廉。天下大乱时渔阳人王松占据涿郡，刘放前往依附。官渡之战后曹操攻占冀州，刘放劝王松投靠曹操，于是王松在收到曹操的招降书信后，率领雍奴、泉州、安次三县归顺。");
            pEntries.Add("three_liu_kun",
                "刘琨（270年—318年6月22日），字越石，中山郡魏昌县（今河北省石家庄市无极县）人，西晋末年、十六国时期政治家、文学家、音乐家、军事家，他曾经在西晋末年于晋阳（今山西太原）坚守了近十年，对抗刘渊和石勒等反晋势力。官至司空、并州刺史、都督并冀幽三州诸军事、侍中、太尉，封广武侯，谥曰湣。刘琨是西汉中山靖王刘胜之后，其祖父刘迈官至相国参军、散骑常侍，父亲刘蕃、胞兄刘舆也曾出任高官，舅舅是尚书郭奕。但同时他也喜好奢靡虚浮的清谈风流，是以大富豪石崇为首的“二十四友”的成员。");
            pEntries.Add("three_liu_yu",
                "宋武帝刘裕（363年4月16日—422年6月26日），字德舆，小字寄奴，彭城郡彭城县绥舆里（今安徽省萧县）人，汉族人，东晋末年至南北朝初期的军事家、政治家，南北朝时期刘宋的开国皇帝。刘裕出身贫寒，最初为北府将领孙无终的司马，在孙恩之乱中初露军事才能，及后更发起义军击败篡位的桓玄，恢复东晋政权，再次扶持晋安帝上位，获得极高名望，不久之后掌握朝政大权。刘裕趁南燕内讧之际而出兵灭燕，随后又平定了卢循之乱，并消灭了刘毅、诸葛长民及司马休之等异己，巩固了自己在东晋国内的地位。此卡以刘裕身为东晋北府将领、讨灭桓玄并连续北伐的臣将阶段收录。");
            pEntries.Add("three_lu_dai",
                "吕岱由郡县小吏进入孙权幕府，长期负责岭南和交州军政。他平定士徽叛乱、恢复吴国对交州的控制，又经营广州及南方海路，使孙吴势力深入岭南。吕岱晚年仍任大司马，在高龄中参与辅政，是吴国任职时间最长的宿将之一。");
            pEntries.Add("three_lu_meng",
                "吕蒙（178年—219年），字子明，汝南富陂（今安徽阜南东南）人，东汉末年孙权麾下的名将。由于为虎威将军，故亦称吕虎威。吕蒙出身贫苦，年少时未曾受过教育，便从军打仗。其姊夫邓当是孙策亲信，吕蒙后来受到孙策的赏识、孙权的提拔。");
            pEntries.Add("three_lu_su",
                "鲁肃（172年—217年），字子敬，徐州临淮郡东城县（今安徽省定远县）人，东汉末年东吴将领、军事家、战略家、外交家、政治家，为孙权策划未来战略蓝图榻上策，在周瑜去世后接替其职务。十分积极提倡联刘抗曹，与诸葛亮十分友好结成孙刘联盟。现代人受三国演义影响，将周瑜、鲁肃、吕蒙、陆逊合称为四大都督，但事实上鲁肃并没有担任过都督一职。");
            pEntries.Add("three_lu_xun",
                "陆逊（183年—245年3月19日），本名陆议，字伯言，吴郡吴县（今江苏省苏州市）人，三国时代吴国军事家、政治家，负责统领吴国军事和政治多年，并同时掌管民事，辅佐太子等。历任吴国大都督、上大将军、丞相。63岁去世，孙休时追谥昭侯。");
            pEntries.Add("three_man_chong",
                "满宠（175前—242年），字伯宁，山阳昌邑人，东汉末年至三国时期曹魏名将，身高八尺，素来以廉洁着称。初任东汉实质首都许县县令，掌管司法，不畏强权而执法严苛。后转任汝南太守，开始参与军事。魏文帝在位期间，驻扎在新野，负责荆州侧对吴作战。");
            pEntries.Add("three_murong_ke",
                "慕容恪（320年—367年），字玄恭，昌黎棘城（今辽宁省义县西北）鲜卑人。十六国时期前燕的政治家、军事家、宗室。前燕文明帝慕容皝的第四子，景昭帝慕容儁弟。慕容恪在前燕屡立军功，不仅安定国家，更攻占东晋领有的洛阳，威震关中，使前燕的国势空前强大，颇有雄据北方，席卷中华大地之趋势。");
            pEntries.Add("three_pang_tong",
                "庞统（179年—214年夏（农历4月）），字士元，东汉末年襄阳郡襄阳县（治所在今湖北省襄阳市襄州区）人。地方上称其「凤雏」，与「卧龙」诸葛亮师出同门与齐名。庞统亦是诸葛亮二姐夫庞山民的堂兄弟，与诸葛亮亦有亲戚关系，当时俗语有云：「卧龙、凤雏，二者得一，可安天下。」被南郡太守周瑜任命为功曹，周瑜死后扶送灵柩回江东吊丧，后成为刘备重臣谋士，协助刘备征伐天府之国的四川之地巴蜀，在攻打首府成都附近重要据点支城雒城时被流矢射中身亡，享年36岁。");
            pEntries.Add("three_pei_xiu",
                "裴秀（224年—271年4月3日），字季彦，河东闻喜县人。曹魏西晋政治家，地图学家。青年起从政，一直颇受司马昭、司马炎父子信任，曾主持魏末晋初官职和爵位的制定工作，官至司空。他着有中国最早有记载的地图集《禹贡地域图》，并在其序中提出了对中国古代地图绘制影响很大的“制图六体” 。");
            pEntries.Add("three_ren_fang",
                "任昉（460年—508年），字彦昇，小字阿堆，乐安博昌（今山东寿光）人。自幼“聪明神悟”，四岁能诵诗，八岁能文，“雅善属文，尤长载笔，声闻藉甚。”叔父任晷夸他“吾家千里驹也。”南朝宋时，举兖州秀才，拜太常博士。");
            pEntries.Add("three_ruan_ji",
                "阮籍是竹林七贤代表人物，身处曹魏末年司马氏逐步夺权的政治环境。他常以饮酒、佯狂和不置可否躲避征辟与婚姻拉拢，曾任步兵校尉，因而又称阮步兵。《咏怀诗》八十二首以隐晦方式表达对名教、权力和人生困境的忧思，对魏晋文学影响深远。");
            pEntries.Add("three_shan_tao",
                "山涛（205年—283年3月3日），字巨源，河内郡怀县（今河南武陟西）人，「竹林七贤」之一。好老庄之学，与嵇康，阮籍等交游，为人小心谨慎，山涛在竹林七贤中年龄最大，一直到四十岁才开始为官。投靠司马氏，仕途平步青云。后山涛见司马懿与曹爽争权，乃隐身不问事务。");
            pEntries.Add("three_shen_yue",
                "沈约（441年—513年），字休文，吴兴郡武康县人（今浙江省德清县西），南朝时的文学家与史学家，历仕刘宋、南齐、南梁三朝。沈约出身于世家豪族，少年孤贫，刘宋至南齐初年在外郡的幕府中担当参军等职，后随太子萧长懋调回京师，担任太子家令等职，以文才见称，为萧长懋与其弟竟陵王萧子良的门客，与谢朓、萧衍等人合称竟陵八友，为一时文学宗师。其后萧衍举兵抗齐，沈约力劝其问鼎帝位，有功于南梁的建立，先后官拜尚书仆射、尚书令、太子少傅。沈约善写乐府，诗歌早期雕琢滞重，中年以后转趋简易流畅，声律方面沈约等人阐发四声理论，提出作诗的四声八病说，开创永明体诗歌。");
            pEntries.Add("three_sima_yi",
                "司马懿（179年—251年9月7日），字仲达，河内郡温县（今河南省焦作市温县）人，三国时期曹魏太傅、政治家、军事家，亦是日后西晋的奠基人。曾抵御蜀汉丞相诸葛亮的北伐军，坚守疆土。历经曹操、曹丕、曹叡、曹芳四代君主，晚年发动高平陵之变，夺取曹魏的政权。为曹魏后期两位权臣司马师和司马昭父亲，晋朝开国皇帝晋武帝司马炎祖父。");
            pEntries.Add("three_sima_zhao",
                "司马昭（211年—265年9月6日），字子上（小说《三国演义》为子尚），河内郡温县（今河南省温县）人，曹魏后期政治家和军事家，晋朝奠基者。司马懿与张春华的次子，司马师之弟，西晋开国皇帝司马炎之父。西晋建立后其子司马炎追尊其为文皇帝，庙号太祖。");
            pEntries.Add("three_tao_hongjing",
                "陶弘景（456年4月30日—536年3月12日；南朝宋孝武帝孝建三年－梁武帝大同二年），字通明，自号华阳隐居，赐号贞白先生，丹阳秣陵（今中华人民共和国江苏省南京市江宁区）人，南朝道士、医学家、文学家与书法家，博学多才，善于描写自然风景，精通医药与天文知识，兼修佛、道二教，特别尊崇东晋时出世的上清经，成为道教上清派的代表人物。南齐时，他担任亲王的侍读多年，有感官职低微，索性辞官隐居不仕，率弟子栖隐茅山，专心修道，却因梁武帝常派人向他谘询国事，而有「山中宰相」的美誉。陶弘景长期炼制丹药，铸炼宝刀，撰有《真诰》、《登真隐诀》、《本草经集注》等道教与医学重要着作，受元代茅山宗追尊为第九代宗师，其渊博知识广受现代史家所推崇。");
            pEntries.Add("three_tao_kan",
                "陶侃（259年—334年7月30日），字士行。孙吴鄱阳郡枭阳县（今江西省都昌县）人，晋朝名将。出身寒门的陶侃自讨平张昌叛乱开始以其战功一直升迁，最终当上太尉之位，并掌握重兵，都督八州军事并任荆江两州刺史；在世族垄断高位的东晋是一个例外。陶侃不单对东晋的建立与维持在军事上作出贡献，本身亦甚有治绩，治下荆州太平安定，路不拾遗，亦深受人民爱戴。");
            pEntries.Add("three_wang_can",
                "王粲（177年—217年2月17日），字仲宣，山阳郡高平县（今山东省济宁市微山县）人。擅长辞赋，建安七子之一，被誉为「七子之冠冕」。王粲出身名门大族，其曾祖父王龚，在汉顺帝时任太尉；祖父王畅，在汉灵帝时任司空，是当时的名士。父亲王谦，曾任大将军何进的长史。");
            pEntries.Add("three_wang_dao",
                "王导（276年—339年9月7日），字茂弘，琅邪临沂（今山东省临沂市）人。是东晋初年权臣，历仕晋元帝、晋明帝和晋成帝三代。他与堂兄王敦及其家族随晋元帝衣冠南渡，并积极联结南方士族以支持晋室，又团结北来侨姓士族，让晋元帝得以在南方立足，并在西晋亡后建立东晋。后王敦发起叛乱，但王导仍然支持晋室，及至乱事平定后身居高位，续获明帝、成帝以及朝中大臣倚重。");
            pEntries.Add("three_wang_jun",
                "王濬（jùn）（206年—286年1月28日），字士治，小字阿童。弘农郡湖县（今河南灵宝西）人，西晋政治人物。王濬出身于世代二千石的官户人家，年轻时就以俊美的外表着称，虽博览坟典，但为人却不修边幅，也不太在意他人眼光，整天游手好闲，因此不受邻里赞誉。后来，王濬认为自己不能虚度光阴，乃洗心革面，立志要做出一番事业。");
            pEntries.Add("three_wang_meng",
                "王猛（325年—375年），字景略，北海郡剧县（今山东潍坊市昌乐县西）人，后移家魏郡。十六国时期重要政治家、军事家，于前秦官至丞相，爵封清河武侯。对前秦富国强兵，统一北方有重要影响。其辅佐前秦朝政长达18年有余，对内整饬法纪、选拔贤才、富国兴邦、兴建水利、打压世族以中央集权，对外首先平定前秦五公之乱，而后统兵先平定西陲诸部，攻灭东面强敌前燕，一役而获157郡，246万户，990万人的广阔领土，故宋书称其为「王猛之相苻坚也，北人以方之诸葛亮」。");
            pEntries.Add("three_wang_sengbian",
                "王僧辩（5世纪—555年10月27日），字君才，太原祁（今山西祁县）人，南梁将领。王僧辩早年随父亲南归南梁，一直跟随着梁武帝子湘东王萧绎，历任中兵参军及贞毅府谘议参军，后任竟陵太守。梁大宝元年（550年），发生侯景之乱，侯景发兵攻至台城，包围梁武帝，萧绎派王僧辩勤王。后侯景攻入建康，以武帝名义解散勤王军队，王僧辩等建议都督柳仲礼讨伐侯景，柳仲礼不听，解散军队，投降侯景，王僧辩也随之投降及入见。");
            pEntries.Add("three_wu_mingche",
                "吴明彻（504年—580年8月24日），字通昭，南兖州秦郡（今江苏省南京市六合区）人，南梁、南陈官员。祖父吴尚，字景安，曾为南齐南谯郡太守，父吴树，南梁右军将军。侯景之乱爆发，秦郡大饥，明彻将粮食分给邻居。承圣三年（554年）三月，陈霸先在京口与吴明彻结交，封他为戎昭将军、安州刺史。");
            pEntries.Add("three_xiang_xiu",
                "向秀（227年—272年），字子期，河内怀县（今河南武陟西南）人，魏晋玄学家、作家，竹林七贤之一。向秀好读书，尤喜老庄之学，山涛曾经偶然间听到向秀谈论《庄子》，惊为天人，两人遂结为忘年交，山涛更将向秀介绍给嵇康与阮籍。与嵇康、吕安等人友善，在山阳隐居。嵇康锻铁，向秀便帮他佐鼓排；吕安种菜，向秀助其灌园，游离于仕途之外。");
            pEntries.Add("three_xiao_daocheng",
                "齐高帝萧道成（427年—482年4月11日），字绍伯，小字鬬将，南兰陵兰陵（今江苏武进）人。南北朝时代军事家、政治家，南朝第二个皇朝南齐开国皇帝。萧道成出身将门，以戎旅起家，屡次征伐外敌、平定内乱有功。刘宋末年政治混乱，道成入朝累官为「四贵」权臣，后来更参预废立，终于篡宋建齐。此卡以萧道成担任刘宋将领和权臣、逐步掌握禁军与朝政的臣僚阶段收录。");
            pEntries.Add("three_xiao_ziyun",
                "萧子云（487年—549年），字景乔，南兰陵（今江苏省常州市西北）人。南梁史学家、文学家、书法家。齐高帝孙，萧嶷第九子，萧子范、萧子显弟。南齐建武四年（497），萧子云受封新浦县侯。");
            pEntries.Add("three_xie_an",
                "谢安（320年—385年10月12日），字安石，陈郡阳夏（今河南省太康县）人，东晋政治家、军事家。曾隐居会稽郡东山（今浙江省上虞区），历任吴兴太守、侍中兼吏部尚书兼中护军、尚书仆射兼领吏部加后将军、扬州刺史兼中书监兼录尚书事、都督五州、幽州之燕国诸军事兼假节、太保兼都督十五州军事兼卫将军等职，死后追赠太傅，追封庐陵郡公。世称谢东山、谢安石、谢相、谢公。他初与权臣周旋时，从不卑躬屈膝，不违背自己的准则却能拒权臣而扶社稷；等他自己当政的时候，又处处以大局为重，不结党营私，不仅调和了东晋内部矛盾，还于淝水之战击败前秦并北伐夺回了大片领土；而到他北伐胜利、正是功成名就之时，还能激流勇退，不恋权位；因此被后世人视为良相的代表，“高洁”的典范。");
            pEntries.Add("three_xie_xuan",
                "谢玄（343年—388年2月8日），字幼度，小名羯儿，因此也有人称呼他为“谢羯”或“谢遏”雅好清谈，与张玄之并称为“南北二玄”，陈郡阳夏县（今河南省周口市太康县）人，东晋大臣、名将、作家，谢安之侄，谢道韫之弟。封康乐县公，谥献武，人称谢献武、康乐献武公。追封车骑将军，是以又被称为“谢车骑”。");
            pEntries.Add("three_xu_shu",
                "徐庶早年任侠，改名后在荆州求学并与诸葛亮、石韬交往。他投奔刘备后分析荆州形势并推荐诸葛亮，促成刘备三顾茅庐。曹操南征时徐庶母亲被俘，他辞别刘备进入曹营，后来在曹魏任官，却未再成为前线决策核心。");
            pEntries.Add("three_xun_you",
                "荀攸（157年—214年），字公达，汉末豫州颍川颍阴（今河南许昌）人，三国时代曹魏着名政治家、军事家。尚书令荀彧的堂侄，荀攸祖父荀昙，官至广陵太守。荀攸被曹操徵为汝南太守，入为尚书，以功封陵树亭侯。魏国初建，又被封为尚书令；建安十九年（214年），荀攸跟从曹操征孙权，在路上去世，追谥曰敬。");
            pEntries.Add("three_xun_yu",
                "荀（xún）彧（yù）（163年—212年），字文若，颍川郡颍阴县（今河南省许昌市魏都区）人，朗陵侯相荀淑之孙。东汉末年的政治家、战略家，亦是曹操谋臣，官至侍中兼光禄大夫，封万岁亭侯，被比喻为如同西汉的张良。曾表示反对曹操称魏公，不久后去世，谥曰敬侯，追赠为太尉。因其曾任尚书令十余年，被称为「荀令君」。");
            pEntries.Add("three_yang_xiu",
                "杨修（175年—219年），亦作杨修，字德祖，弘农华阴（今陕西华阴东）人，袁术之外甥，太尉杨彪之子，出身高门士族。远祖杨喜是汉高祖时的猛将，祖先杨敞是汉昭帝的宰相。杨贲生杨谭，杨谭生杨宝，相传杨宝心善，因为救了黄雀而得到「衔环」的报恩。杨宝生杨震，杨震生杨秉，杨秉生杨赐，杨赐生杨彪，从杨震到杨彪，四代都当到太尉。");
            pEntries.Add("three_yuan_zan",
                "元赞是北魏宗室与官员，活动于北魏政权逐步汉化并重组宗室权力的时期。他以宗室身份参与朝廷礼制、地方治理及宗族事务，政治地位受到皇室内部关系影响。现存资料对其个人事迹保存有限，本卡据北朝臣僚身份单独收录，不与其他时代同名人物混同。");
            pEntries.Add("three_yuan_shao",
                "袁绍字本初，出身汝南袁氏，东汉末年以诛除宦官、反对董卓而取得政治声望，并被关东诸侯推为盟主。他先后击败公孙瓒、控制冀青幽并四州，建立当时北方规模最大的割据势力，但集团内部在继承安排和谋臣路线之间长期分裂。建安五年袁绍在官渡之战败于曹操，退回河北后病逝，其诸子相争使袁氏势力最终被曹操逐步消灭。");
            pEntries.Add("three_yuwen_tai",
                "宇文泰（505年—556年11月21日），字黑獭（一作黑泰），代郡武川镇（今内蒙古自治区呼和浩特市武川县）人，鲜卑宇文部后裔，北朝西魏权臣，爵封「安定公」，谥「文」，亦是北周政权的奠基者，掌权22年。后追尊为文王，庙号太祖，武成元年（559年）追尊为文皇帝。此卡以宇文泰辅佐西魏、主持府兵与关陇集团建设的权臣身份收录。");
            pEntries.Add("three_zhang_liao",
                "张辽（169年—222年），字文远，雁门郡马邑县（今山西省朔州市朔城区）人。本姓聂，是西汉聂壹之后，为避祸改姓张。东汉末、三国时期曹魏前将军，五子良将之一，谥号为刚侯。后为历代所推崇，唐朝时位列古今六十四名将之一。");
            pEntries.Add("three_zhang_fei",
                "张飞字益德，涿郡人，东汉末年与关羽一同追随刘备，长期担任刘备集团的前线将领。长坂坡撤退时他率少数骑兵据守当阳桥阻挡曹军，入蜀后又与赵云、诸葛亮分兵平定郡县，并在巴西之战击败曹魏名将张郃。刘备称帝后张飞任车骑将军、领司隶校尉，准备伐吴期间因治军严酷被部下范强、张达杀害，蜀汉追谥桓侯。");
            pEntries.Add("three_zhao_yun",
                "赵云（？年—229年），字子龙，是汉末三国时期的蜀汉武将，生于常山真定（今河北省正定县），据《赵云别传》记载，赵云身长八尺，姿颜雄伟。其早年从属公孙瓒，后转投刘备，并继续仕于刘禅。历任牙门将军，偏将军、领桂阳太守，翊军将军，领中护军、征南将军，封永昌亭侯，镇东将军。后追谥曰顺平侯，是为永昌亭顺平侯。");
            pEntries.Add("three_zhou_yu",
                "周瑜（175年—210年），字公瑾，人称「周郎」，庐江郡舒县（今安徽省舒城县）人，东汉末年孙吴阵营首要的统帅。周瑜为人相貌俊美、天资聪颖、精熟音律，酒过三巡仍能听出宴席间的音误，故传「曲有误，周郎顾」，深得孙策、孙权器重。周瑜年少与孙策情同兄弟，称总角之交，二十岁时与孙策渡过长江击败刘繇，严白虎，王朗等江东割据势力，随孙策平定江东。建安五年，孙策遇刺身亡，孙权继任，周瑜将兵赴丧还吴，以中护军的身份与长史张昭共掌众事。");
            pEntries.Add("three_zhuge_liang",
                "诸葛亮（181年—234年10月8日），字孔明，琅琊郡阳都县（今山东省临沂市沂南县）人。三国时期蜀汉（季汉）丞相，亦是政治家、军事家、发明家及散文家，曾发明木牛流马、诸葛连弩等。他常被后世认为是智慧和忠义的典范。先为刘备麾下核心幕僚，后主刘禅早期蜀汉实际上的最高领导人。");
            pEntries.Add("three_zu_chongzhi",
                "祖冲之（429年—500年），字文远，范阳郡逎县（今河北省保定市涞水县）人，刘宋时代杰出的数学家、天文学家，主要成就在数学、天文历法和机械制造三个领域。祖冲之的儿子祖暅也是数学家。祖家历代都对天文历法素有研究，祖冲之从小就有机会接触天文、数学知识。祖冲之青年时，就得到博学多才的名誉，宋孝武帝听说后，派他到华林学省做研究工作。");
            pEntries.Add("three_zu_ti",
                "祖逖（266年—321年），字士稚，范阳郡逎县（今河北省保定市涞水县）人，东晋初期北伐将领。成语“闻鸡起舞”讲的就是他和刘琨的故事。祖逖曾一度收复黄河以南大片土地，但及后因朝廷内乱，在他死后北伐功败垂成。祖逖亦是一位极受人民爱戴的将领，他死后，所辖的豫州人人都好像父母离世那样悲伤。");
            pEntries.Add("tufa_wugu",
                "武威武王秃发乌孤（4世纪—399年），河西鲜卑人，十六国时期南凉政权建立者。秃发鲜卑首领，称武威王，其父秃发思复鞬亦为秃发鲜卑族首领。秃发乌孤是秃发鲜卑首领秃发思复鞬的长子。394年秃发思复鞬死后，秃发乌孤接任秃发鲜卑首领，他勇猛威武，且有大志，并图谋夺取时由后凉控制的凉州。");
            pEntries.Add("wei_feidi",
                "曹芳（232年—274年），字兰卿，魏明帝养子，是三国时曹魏皇帝，在位15年。在《三国志》中与其被迫退位之后继任的曹髦、曹奂合称三少帝。曹芳是曹魏在位最久的君主，但也是曹魏第一位傀儡皇帝，实权先后由曹爽、司马懿和司马师掌握。");
            pEntries.Add("wei_mingdi",
                "魏明帝曹叡（ruì）（204年—239年1月22日），字元仲，豫州沛国谯县（今安徽省亳州市）人。三国时期曹魏皇帝（226年至239年在位）。魏文帝曹丕长子，母为文昭甄皇后。黄初三年（222年），曹叡封平原王，黄初七年（226年）五月，魏文帝病重，立曹叡为皇太子，即位于洛阳。");
            pEntries.Add("wei_wendi",
                "魏文帝曹丕（187年—226年6月29日），字子桓，沛国谯县（今属安徽省亳州市）人。三国时期曹魏的开国皇帝，是曹操和武宣卞皇后的嫡长子。曹丕在曹操去世之后继承父亲的魏王封号与丞相的大权，并最终在公元220年使东汉汉献帝禅让于他。登基称帝后改国号为魏，史称曹魏，226年驾崩，谥文皇帝。");
            pEntries.Add("wei_yuandi",
                "魏元帝曹奂（246年—302年），原名璜，字景明，是曹魏最后一位皇帝，260年到266年在位。曹奂是燕王曹宇之子，曹操之孙，初封常道乡公。甘露五年（260年）魏帝曹髦试图从司马氏手中夺回权力失败，兵败被杀，丞相司马昭派儿子使持节行中护军中垒将军司马炎去东武阳迎立曹璜为皇帝，改名曹奂，入继为堂兄魏明帝曹叡的儿子。曹奂实际上毫无权力，在大臣和军队中也没有任何势力，完全是司马昭的傀儡。");
            pEntries.Add("wei_zhengdi",
                "曹髦（241年11月15日—260年6月2日），字彦士，三国时期曹魏皇帝（254年－260年在位），曹霖之子，魏文帝曹丕孙。在《三国志》中与其前任者曹芳、继任者曹奂合称三少帝。正始五年（244年），封郯县高贵乡公。254年，司马师废掉时年23岁曹芳的皇位，打算立曹操之子彭城王曹据为皇帝。");
            pEntries.Add("wu_dadi",
                "吴大帝孙权（182年7月5日—252年5月21日），字仲谋，生于下邳（今江苏省徐州市睢宁县北郊），籍贯吴郡富春。东汉末年至三国时期的政治家、军事统帅，孙吴政权奠基者和开国皇帝，亦被视为六朝江东政权的开端人物之一。孙权为破虏将军孙坚次子、讨逆将军孙策之弟。200年孙策死后，孙权继承江东基业，在张昭、周瑜、鲁肃等人辅佐下逐步稳固统治。");
            pEntries.Add("wu_hui_zhu",
                "孙亮（244年—260年），字子明，是中国三国时代吴国君主，在位六年（252年-258年）。后世史书多称之为吴少帝、吴废帝，或用他被废位时得到的封号会稽王。孙亮生于赤乌七年（244年），是吴大帝孙权的幼子，因此特别受到疼爱。孙亮出生的时候，他的长兄孙登、二兄孙虑早已去世，当时的皇太子为三兄孙和。");
            pEntries.Add("wu_jingdi",
                "吴景帝孙休（235年—264年9月3日），字子烈，为孙权第六子，在父亲孙权、弟孙亮后继任为吴国皇帝，在位六年。孙休生于嘉禾四年（235年），母王夫人，13岁时，跟随谢慈和盛冲就学。太元二年（252年）受封为琅琊王，居于虎林，当时十八岁。同年四月，大帝因患风疾病死于建业，孙休的嫡弟孙亮继位，由太傅诸葛恪秉政，诸葛恪不欲诸王在滨江兵马之地，遂徙孙休至丹杨郡。");
            pEntries.Add("wu_moding",
                "吴末帝孙皓（243年—284年），字元宗，幼名彭祖，又字皓宗，《三国志》原名为孙晧。为废太子孙和之子，吴大帝孙权之孙，在位约十六年（264年—280年），是三国时期东吴的第四位，同时也是三国最后一位皇帝。吴景帝孙休逝世时，太子非常年幼。因当时吴国处于内忧外患之中，大臣们便合议改立较年长的孙皓即位。");
            pEntries.Add("xiao_cha",
                "梁宣帝萧詧（chá）（519年—562年），字理孙，梁武帝之孙、昭明太子萧统之第三子。为西梁的建立者，谥号宣皇帝，庙号中宗。萧统死后，梁武帝立萧纲为皇太子，而进封萧统诸子为王。萧詧被封为岳阳郡王并被任命为东扬州刺史，镇守会稽。");
            pEntries.Add("xiwei_feidi",
                "魏废帝元钦（525年—554年），河南郡洛阳县（今河南省洛阳市东）人，西魏文帝元宝炬长子，生母乙弗皇后，西魏第二代皇帝。大统元年（535年），元宝炬登基建立西魏时，元钦被立为皇太子。不久丞相宇文泰主动许配女儿给元钦，成为元钦的岳父。大统十七年（551年），文帝驾崩，太子元钦即位，沿用文帝年号，次年（552年）去年号，称元年。");
            pEntries.Add("xiwei_gongdi",
                "魏恭帝拓跋廓（537年—557年），原姓元，河南郡洛阳县（今河南省洛阳市东）人，西魏文帝元宝炬四子，西魏十二大将军之一，后为西魏末代皇帝。拓跋廓在西魏官至使持节、大将军、大都督，封齐王。大统十六年（550年），齐文宣帝高洋称帝，宇文泰发动关中兵马讨伐北齐，西魏文帝元宝炬派遣齐王拓跋廓镇守陇右，征召陇右大都督宇文导回朝镇守咸阳。元廓的兄长元钦继位后于554年被权臣宇文泰所废，宇文泰立元廓为帝，去年号称元年，并且复姓拓跋。");
            pEntries.Add("xiwei_wendi",
                "魏文帝元宝炬（507年—551年3月28日），河南郡洛阳县（今河南省洛阳市东）人，魏孝文帝元宏之孙，京兆王元愉第三子，母杨奥妃，南北朝时代西魏第一位皇帝。元宝炬在魏宣武帝时因为父亲获罪受牵连，年幼的一众兄弟皆被幽禁在宗正寺，在宣武帝死后才重获自由，被叔叔元怿收养。武泰年间封邵县侯，530年被封为南阳王。534年跟随堂弟魏孝武帝元修入关中投靠宇文泰。");
            pEntries.Add("yao_chang",
                "秦武昭帝姚苌（约330年—394年），字景茂。南安郡赤亭（今甘肃省陇西县西）人，十六国时期后秦政权的开国君主。后赵末年南安古羌酋长姚弋仲第二十四子，姚襄之弟。姚苌在姚襄死后率其部众入秦，成为前秦的将领。");
            pEntries.Add("yuwen_tai",
                "宇文泰（505年—556年11月21日），字黑獭（一作黑泰），代郡武川镇（今内蒙古自治区呼和浩特市武川县）人，鲜卑宇文部后裔，北朝西魏权臣，爵封「安定公」，谥「文」，亦是北周政权的奠基者，掌权22年。后追尊为文王，庙号太祖，武成元年（559年）追尊为文皇帝。此卡以宇文泰作为北周制度奠基者并被后世追尊太祖的政权创建者身份收录。");
            pEntries.Add("zhang_gui",
                "张轨（255年—314年6月22日），字士彦，安定郡乌氏县（今宁夏固原市东南彭阳县）人。西汉常山王张耳的十七世孙。西晋时任凉州刺史，是前凉政权奠定者，张寔、张茂皆为其子。至其曾孙张祚时，追谥为武王，庙号太祖。");
            pEntries.Add("zhou_xiaomin",
                "周孝闵帝宇文觉（542年—557年），字陀罗尼，代郡武川镇（今内蒙古自治区呼和浩特市武川县）人，北朝西魏权臣宇文泰嫡长子，爵封“周公”，南北朝时代北周的第一位君主，号称天王，但实际上是权臣宇文护的傀儡。557年宇文护拥立宇文觉即位为天王，建立北周。此卡强调宇文觉承接宇文泰事业、建立周政权的开国君主名义。");
        }
    }
}
